<script setup>
import { computed,ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { ArrowRight,Info,AlertTriangle } from 'lucide-vue-next'
import { ElMessage } from 'element-plus'
import PageTitle from '../components/PageTitle.vue'
import FileUpload from '../components/FileUpload.vue'
import { state,taskById,money,income,uid,stamp } from '../lib/store'
import { requireRole,confirm,notify } from '../lib/actions'
const route=useRoute(),router=useRouter(),task=computed(()=>taskById(route.params.id)),form=ref(null),files=ref([]),model=ref({quote:task.value?Math.min(1100,task.value.price):0,days:3,description:''}),busy=ref(false)
const already=computed(()=>state.bids.some(b=>b.taskId===task.value?.id)),fee=computed(()=>Math.round(model.value.quote*100)-income(Math.round(model.value.quote*100)))
const rules={quote:[{required:true,message:'请输入报价',trigger:'blur'},{validator:(_,v,cb)=>v>0&&v<=task.value.price?cb():cb(new Error('报价须大于 0 且不超过任务赏金')),trigger:'change'}],description:[{required:true,min:20,max:500,message:'请填写 20–500 字方案说明',trigger:'blur'}]}
async function submit(){if(busy.value||already.value)return;if(!requireRole(router,'creator',true))return;try{await form.value.validate()}catch{return}if(model.value.quote<task.value.price*.5&&!(await confirm('报价低于任务赏金的 50%，请确认能保证作品质量。','确认低价投标')))return;busy.value=true;state.bids.unshift({id:uid('B'),taskId:task.value.id,title:task.value.title,art:task.value.art,cents:Math.round(model.value.quote*100),days:model.value.days,description:model.value.description,files:files.value.map(f=>({name:f.name,size:f.size})),status:'待选中标',at:stamp()});if(!state.bookmarks.includes(task.value.id))state.bookmarks.push(task.value.id);notify('演示投标已提交，可在我的投标中查看');router.push('/creator/bids')}
</script>
<template><main id="page-content" class="page-container app-ui"><template v-if="task&&task.mode==='比稿'"><div class="breadcrumbs"><RouterLink to="/tasks">任务广场</RouterLink><span>/</span><RouterLink :to="`/tasks/${task.id}`">{{task.title}}</RouterLink><span>/</span>提交投标</div><PageTitle title="提交你的创作方案" description="说清思路，让商家看见你的创作优势。"/><div class="columns wide-left"><div class="stack"><div class="panel bid-task"><img :src="task.image" alt="任务参考"/><div><h3>{{task.title}}</h3><div class="tag-row"><span class="plain-tag">{{task.category}}</span><span class="plain-tag">比稿</span><span class="muted">{{task.days}} 天内交付</span></div></div></div><section class="panel"><el-form ref="form" :model="model" :rules="rules" label-position="top"><div class="form-grid"><el-form-item label="报价（元）" prop="quote"><el-input-number v-model="model.quote" :min="1" :max="task.price" :precision="2" :controls="false"/><p class="field-help">不得超过任务赏金 ¥{{task.price}}</p></el-form-item><el-form-item label="交付工期" required><el-select v-model="model.days"><el-option v-for="i in task.days" :key="i" :label="`${i} 天`" :value="i"/></el-select></el-form-item></div><el-form-item label="方案说明" prop="description"><el-input v-model="model.description" type="textarea" :rows="7" placeholder="简要说明创作思路、风格把控、交付计划与相关经验……" maxlength="500" show-word-limit/></el-form-item><el-form-item label="作品集附件（选填）"><FileUpload v-model="files" :video="false" label="添加作品"/></el-form-item></el-form></section></div><aside class="panel"><h2>任务摘要</h2><div class="data-lines"><div><label>预算赏金</label><strong class="price-text">¥{{task.price}}</strong></div><div><label>招募剩余时间</label><strong>{{Math.floor(task.remaining/24)}} 天 {{task.remaining%24}} 小时</strong></div><div><label>已投标</label><strong>{{task.bids||0}} 人</strong></div><div><label>免费修改</label><strong>{{task.revisions}} 轮</strong></div></div><div class="divider"/><h3>你的收益预估 <Info :size="15"/></h3><div class="data-lines"><div><label>报价金额</label><strong>¥{{money(Math.round(model.quote*100))}}</strong></div><div><label>平台服务费 15%</label><strong>− ¥{{money(fee)}}</strong></div><div><label>预计实得</label><strong class="price-text big-number">¥{{money(income(Math.round(model.quote*100)))}}</strong></div></div><div class="info-note warning" style="margin:20px 0"><AlertTriangle/>每个任务仅可投标 1 次，提交后不可撤回；有效期为 72 小时。</div><el-button type="primary" class="full-button" :disabled="already||busy||!!(task.status&&task.status!=='招募中')" @click="submit">{{already?'你已提交投标':'提交投标'}}<ArrowRight/></el-button><el-button class="full-button" style="margin-top:12px" @click="router.push(`/tasks/${task.id}`)">返回任务详情</el-button></aside></div></template><el-empty v-else description="该任务不存在或不支持投标"><el-button @click="router.push('/tasks')">返回任务广场</el-button></el-empty></main></template>
<style scoped>.bid-task{display:flex;align-items:center;gap:20px}.bid-task>img{width:115px;height:76px;border-radius:6px;object-fit:cover;object-position:left}.bid-task h3{margin-bottom:10px}@media(max-width:650px){.bid-task{gap:12px}.bid-task>img{width:80px;height:72px}.bid-task h3{font-size:15px}}</style>
